  const queryRows=rows=>rows.filter(r=>!api.getQuery()||JSON.stringify(r).toLocaleLowerCase('pt-BR').includes(api.getQuery().toLocaleLowerCase('pt-BR')));
  const statusLabels={ativo:'Ativo',concluido:'Concluído',arquivado:'Arquivado',pendente:'Pendente',concluida:'Concluída',cancelada:'Cancelada',confirmado:'Confirmado',cancelado:'Cancelado',rascunho:'Rascunho',ativa:'Ativa',pausada:'Pausada',programada:'Programada',preparada:'Preparada',manual:'Envio manual registrado',executando:'Executando',aguardando:'Aguardando',ignorada:'Condição não atendida',erro:'Erro',baixa:'Baixa',normal:'Normal',alta:'Alta',urgente:'Urgente'};
