  let taskMode='list',taskTab='todas',taskFilters={owner:'',projectId:'',priority:''},calendarMode='month',calendarDay=today(),calendarOwner='',journeyDraft,stepDraftRows,selectedDashboard='',managementFilters={from:'',to:'',owner:'',pipelineId:''},reportMetric='wonValue',reportGroup='owner',selectedReport='',campaignFilter='';

  function taskRows(){const now=Date.now();return queryRows(S().activities).filter(a=>(!taskFilters.owner||a.owner===taskFilters.owner)&&(!taskFilters.projectId||a.projectId===taskFilters.projectId)&&(!taskFilters.priority||a.priority===taskFilters.priority)&&(taskTab==='todas'||taskTab==='hoje'&&a.due.startsWith(today())||taskTab==='atrasadas'&&a.status==='pendente'&&Date.parse(a.due)<now||taskTab==='proximas'&&a.status==='pendente'&&a.due.slice(0,10)>today()||taskTab===a.status)).sort((a,b)=>a.due.localeCompare(b.due));}
