  function taskControls(){return `<label class="sr" for="opTaskOwner">Responsável</label><select id="opTaskOwner">${options(owners(),taskFilters.owner,'Todos os responsáveis')}</select><label class="sr" for="opTaskProject">Projeto</label><select id="opTaskProject">${options(S().projects.map(p=>[p.id,p.name]),taskFilters.projectId,'Todos os projetos')}</select><label class="sr" for="opTaskPriority">Prioridade</label><select id="opTaskPriority">${options(selectOptions(['baixa','normal','alta','urgente']),taskFilters.priority,'Todas as prioridades')}</select><div class="viewgroup">${button('Lista','opTaskList','',taskMode==='list'?'selected':'')}${button('Quadro','opTaskBoard','',taskMode==='board'?'selected':'')}</div>`;}
