  function renderWork(){const rows=S().activities.filter(a=>a.status==='pendente'&&(!taskFilters.owner||a.owner===taskFilters.owner)).sort((a,b)=>a.due.localeCompare(b.due));api.setRows(rows);const due=rows.filter(a=>Date.parse(a.due)<Date.now()),todayRows=rows.filter(a=>a.due.startsWith(today())),finished=S().activities.filter(a=>a.status==='concluida'&&(!taskFilters.owner||a.owner===taskFilters.owner)&&dateOnly(a.completedAt||'')===today());pageActions(button('＋ Projeto','opNewProject')+button('＋ Atividade','newActivity','','primary'));
    content(`<div class="workintro"><div><h2>Seu trabalho, em ordem.</h2><p>${new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'})}</p></div><label>Responsável<select id="opWorkOwner">${options(owners(),taskFilters.owner,'Todos')}</select></label></div><div class="workstats"><span><strong>${due.length}</strong> em atraso</span><span><strong>${todayRows.length}</strong> para hoje</span><span><strong>${finished.length}</strong> concluídas hoje</span></div><div class="twocol"><section class="panel"><h2>Próximas atividades</h2>${rows.slice(0,10).map(a=>`<div class="workitem"><div>${button(a.title,'opTaskDetail',a.id,'linkbutton')}<p>${date(a.due)} · ${esc(projectName(a.projectId))}</p></div>${button('Concluir','completeActivity',a.id)}</div>`).join('')||'<p class="muted">Sua lista está em dia. Cadastre uma atividade para começar.</p>'}</section><section class="panel"><h2>Projetos em andamento</h2>${S().projects.filter(p=>p.status==='ativo'&&(!taskFilters.owner||p.owner===taskFilters.owner)).map(p=>projectSummary(p)).join('')||'<p class="muted">Crie projetos para agrupar tarefas por cliente, campanha ou objetivo.</p>'}</section></div><p class="notice">Lembretes locais: acompanhe as atividades de hoje e em atraso nesta tela. Notificações e execução com o navegador fechado não estão conectadas a um servidor.</p>`);}
  function projectSummary(p){const tasks=S().activities.filter(a=>a.projectId===p.id&&a.status!=='cancelada'),done=tasks.filter(a=>a.status==='concluida').length;return `<div class="projectsummary"><div class="statline">${button(p.name,'opProjectDetail',p.id,'linkbutton')}<span>${done}/${tasks.length} concluídas</span></div><progress max="${tasks.length||1}" value="${done}" aria-label="Progresso de ${esc(p.name)}"></progress><p class="muted">${esc(p.owner||'Eu')} · ${p.due?date(p.due):'Sem prazo'}</p></div>`;}
  function renderProjects(){const rows=queryRows(S().projects);api.setRows(rows);pageActions(button('＋ Projeto','opNewProject','','primary'));content(toolbar()+table(['Projeto','Responsável','Prazo','Progresso','Status','Ações'],rows.map(p=>{const tasks=S().activities.filter(a=>a.projectId===p.id&&a.status!=='cancelada'),done=tasks.filter(a=>a.status==='concluida').length;return [button(p.name,'opProjectDetail',p.id,'linkbutton'),esc(p.owner),p.due?date(p.due):'—',`${done}/${tasks.length} atividades`,badge(p.status),button('Editar','opEditProject',p.id)];}),'Crie um projeto e vincule suas atividades.'));}
  function editProject(key=''){const old=S().projects.find(p=>p.id===key),p=old||{owner:'Eu',status:'ativo'};opForm(key?'Editar projeto':'Novo projeto',`<div class="fields">${field('name','Nome do projeto',p.name,{required:true,wide:true})}${field('owner','Responsável',p.owner,{required:true})}${field('due','Prazo',p.due,{type:'date'})}${field('status','Status',p.status,{options:selectOptions(['ativo','concluido','arquivado'])})}${field('notes','Objetivo e observações',p.notes,{type:'textarea',wide:true})}</div>`,values=>{if(change(s=>put(s,'projects',{...old,...values,id:key||undefined}),'Projeto salvo.'))closeDialog();});}
